using JTradeERP.Application.Common.Exceptions; using JTradeERP.Application.Common.Persistence; using JTradeERP.Domain.Security; using MediatR;
namespace JTradeERP.Application.Features.Security.Administration.GetRoleById;
public sealed record GetRoleByIdQuery(Guid Id):IRequest<GetRoleByIdResponse>; public sealed record RolePermissionResponse(Guid PermissionId,string Code,Capability Capability); public sealed record GetRoleByIdResponse(Guid Id,string Name,IReadOnlyCollection<RolePermissionResponse> Permissions);
public sealed class GetRoleByIdHandler(IApplicationDbContext db):IRequestHandler<GetRoleByIdQuery,GetRoleByIdResponse>{public Task<GetRoleByIdResponse> Handle(GetRoleByIdQuery r,CancellationToken ct){var role=db.Roles.SingleOrDefault(x=>x.Id==r.Id)??throw new NotFoundException("Role was not found.");var grants=(from rp in db.RolePermissions join p in db.Permissions on rp.PermissionId equals p.Id where rp.RoleId==r.Id select new RolePermissionResponse(p.Id,p.Code,rp.Capability)).ToArray();return Task.FromResult(new GetRoleByIdResponse(role.Id,role.Name,grants));}}
public static class GetRoleByIdEndpoint{public static void Map(IEndpointRouteBuilder e)=>e.MapGet("/roles/{id:guid}",async(Guid id,ISender s,CancellationToken t)=>Results.Ok(await s.Send(new GetRoleByIdQuery(id),t))).RequirePermission("Admin.Roles.Manage",Capability.Full);}
